        vm.assume(dao != address(0));
        vm.assume(target != address(0));
        vm.assume(emergency == false);
        // Set DAO as the caller
        vm.prank(dao);
        c.setDAO(dao);
        // Configure flash governance to allow assertGovernanceApproved to succeed
        // Need an ERC20 token that can be transferred
        // But for the invariant we just need to not revert on setDAO after the call
        // Instead of full setup, just check that setDAO can be called after assertGovernanceApproved
        // We'll make assertGovernanceApproved revert or succeed, then test setDAO
        // For the reference, after any call to assertGovernanceApproved (even if it reverts),
        // setDAO should work if configured is false and caller is DAO.
        // Since configured is false by default, and we set DAO to caller, setDAO should succeed.
        // The bug changes the condition to require configured, so it will revert if configured is false.
        // We test this directly:
        (bool success,) = address(c).call(abi.encodeWithSignature("assertGovernanceApproved(address,address,bool)", dao, target, emergency));
        // Now try to call setDAO with a new DAO address
        vm.prank(dao);
