contract InvMutTest is Test {
    C c;
    address constant ASSET = address(0x1);
    address constant SENDER = address(0x2);
    address constant TARGET = address(0x3);

    function setUp() public {
        c = new C(address(this));
        // Set up flash governance config
        vm.store(address(c), bytes32(uint256(3)), bytes32(uint256(100))); // amount
        vm.store(address(c), bytes32(uint256(4)), bytes32(uint256(0))); // unlockTime
        vm.store(address(c), bytes32(uint256(5)), bytes32(uint256(uint160(ASSET)))); // asset
        vm.store(address(c), bytes32(uint256(6)), bytes32(uint256(1))); // assetBurnable
        // Set security parameters
        vm.store(address(c), bytes32(uint256(8)), bytes32(uint256(1000))); // epochSize
        vm.store(address(c), bytes32(uint256(7)), bytes32(uint256(block.timestamp))); // lastFlashGovernanceAct
        // Make SENDER governed
        vm.store(address(c), keccak256(abi.encode(SENDER, uint256(11))), bytes32(uint256(1)));
        // Make SENDER have enough asset and approve
        deal(ASSET, SENDER, 1000);
        vm.prank(SENDER);
        IERC20(ASSET).approve(address(c), 1000);
    }

    function testFuzz_property(bool emergency, uint256 timeJump) public {
        // Ensure epoch condition fails: timeJump <= epochSize (1000)
        timeJump = bound(timeJump, 0, 1000);
        vm.warp(block.timestamp + timeJump);

        // Call assertGovernanceApproved
        vm.prank(SENDER);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.assertGovernanceApproved.selector, SENDER, TARGET, emergency));

        // For emergency=true, timeJump <= 1000 => should revert in reference (epoch condition fails)
        // Buggy version with !emergency will succeed when emergency=true, timeJump <= 1000
        bool referenceReverted = emergency && timeJump <= 1000;
        bool actualReverted = !success;

        // Since we know the bug only changes behavior when emergency=true and timeJump <= 1000
        // the reference always has referenceReverted == actualReverted for this case
        // But we want to assert something the reference satisfies and bug breaks:
        // For emergency=true and timeJump <= 1000, the reference reverts (actualReverted == true)
        // The buggy version would succeed (actualReverted == false)
        // So we assert: (emergency && timeJump <= 1000) implies actualReverted
        assertTrue(!(emergency && timeJump <= 1000) || actualReverted);
    }
}

